refsection.programlisting:
// (1 + x^2 + x^3) / (1 + x) sobre GF(2)
[r, q] = gf_poly_divide([1 0 1 1], [1 1], 2)   // r = 1, q = [0 0 1] (x^2)

// x^2 + 2 = (x + 2)(x + 1) sobre GF(3)
[r, q] = gf_poly_divide([2 0 1], [1 1], 3)     // r = 0, q = [2 1]

// El dividendo tiene menor grado que el divisor
[r, q] = gf_poly_divide([1 1], [1 0 1], 2)     // r = [1 1], q = 0
